/* 【糯叽机】无声回信（黑）by黛 · 原版完整界面 SullyOS 适配 v2
   基于作者原版 CSS 的聊天布局、悬浮玻璃顶栏与输入栏、连发气泡、铭牌、
   独立头像边框、引用、媒体、转账、心象及群聊。无其他应用的选择器。
   注意：不能再给未显示头像的容器绘制边框，否则会产生一列空圆。 */
.sully-chat-root {
  --silent-ink:#1a1a1a;
  --silent-muted:#8e8e8e;
  --silent-glass:rgba(255,255,255,.75);
  --silent-light-shadow:inset 0 2px 4px rgba(255,255,255,1),0 4px 10px rgba(0,0,0,.05);
  color:#1a1a1a;
}
/* 1. 原版：透明悬浮顶栏 + 毛玻璃渐隐，而不是整块纯白顶部。 */
.sully-chat-root .sully-chat-header {
  background:transparent!important;
  border:0!important;
  box-shadow:none!important;
  min-width:0!important;
  position:relative!important;
  isolation:isolate;
  gap:0!important;
}
.sully-chat-root .sully-chat-header::before {
  content:"";position:absolute;inset:0 0 -18px;
  background:linear-gradient(to bottom,rgba(255,255,255,.66) 0%,rgba(255,255,255,.40) 57%,rgba(255,255,255,0) 100%);
  backdrop-filter:blur(4px) saturate(120%);
  -webkit-backdrop-filter:blur(4px) saturate(120%);
  mask-image:linear-gradient(to bottom,#000 45%,transparent 100%);
  -webkit-mask-image:linear-gradient(to bottom,#000 45%,transparent 100%);
  pointer-events:none;z-index:-1;
}
.sully-chat-root .sully-chat-header > div {min-width:0!important;}
.sully-chat-root .sully-chat-header .sully-chat-back {
  width:44px!important;height:44px!important;
  display:grid!important;place-items:center!important;
  flex:0 0 44px!important;min-width:44px!important;
  margin:0!important;padding:0!important;
  border:0!important;border-radius:40px!important;
  background:var(--silent-glass)!important;
  box-shadow:var(--silent-light-shadow)!important;
  color:#1a1a1a!important;position:relative!important;
  overflow:visible!important;
}
/* 原作返回贴纸。在线图片不可用时必须保留糯米机原生返回箭头。 */
.sully-chat-root .sully-chat-back::after {
  content:"";position:absolute;inset:8px;
  background:url("https://imgbed.heliar.top/i/MpjBV14ad4s7XFLj_IMG_5823.png") center/contain no-repeat;
  pointer-events:none;opacity:.9;
}
.sully-chat-root .sully-chat-profile {
  min-width:0!important;max-width:100%!important;
  padding:4px 11px 4px 7px!important;
  margin:0 6px!important;
  height:48px!important;
  border:0!important;border-radius:40px!important;
  background:var(--silent-glass)!important;
  box-shadow:var(--silent-light-shadow)!important;
  flex:1 1 auto!important;
  gap:7px!important;
  overflow:visible!important;
}
.sully-chat-root .sully-chat-profile .sully-chat-avatar {
  width:30px!important;height:30px!important;
  flex-shrink:0!important;object-fit:cover;
  border-radius:50%!important;
  border:0!important;box-shadow:none!important;
  padding:0!important;
}
.sully-chat-root .sully-chat-info {
  min-width:0!important;max-width:100%!important;
  flex:1 1 auto!important;
  overflow:hidden;
}
.sully-chat-root .sully-chat-name {
  color:#1a1a1a!important;
  font-size:14px!important;font-weight:750!important;
  max-width:100%!important;
  overflow:hidden!important;text-overflow:ellipsis!important;white-space:nowrap!important;
  line-height:1.2!important;
}
.sully-chat-root .sully-chat-name::after {
  content:"";display:inline-block;vertical-align:middle;
  width:17px;height:17px;margin-left:3px;
  background:url("https://i.imgant.com/v2/yKBpk8C.png") center/contain no-repeat;
  pointer-events:none;
}
.sully-chat-root .sully-chat-status {
  color:#8e8e8e!important;
  font-size:10px!important;line-height:1.3!important;
  min-width:0!important;max-width:100%!important;
  flex-wrap:nowrap!important;
}
.sully-chat-root .sully-chat-status::after {
  content:"@Star1nthesky";color:#8e8e8e;font-size:10px;
  display:inline-block;min-width:0;max-width:100%;
  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;
  margin-left:3px;
}
.sully-chat-root .sully-chat-token {
  background:#ffffffc4!important;
  color:#888!important;border-color:#eee!important;
  border-radius:9px!important;
}
.sully-chat-root .sully-chat-trigger {
  width:43px!important;height:44px!important;
  min-width:43px!important;flex:0 0 43px!important;
  margin:0!important;padding:9px!important;
  color:#1a1a1a!important;
  background:var(--silent-glass)!important;
  border:0!important;border-radius:40px!important;
  box-shadow:var(--silent-light-shadow)!important;
  position:relative!important;
}
.sully-chat-root .sully-chat-trigger::after {
  content:"";pointer-events:none;position:absolute;inset:7px;
  background:url("https://imgbed.heliar.top/i/prPUomz7jlBOosJJ_IMG_5820.png") center/contain no-repeat;
}
.sully-chat-root .sully-chat-header button[aria-label]:not(.sully-chat-back):not(.sully-chat-trigger) {
  border-radius:40px!important;
}
.sully-chat-root .sully-chat-buffs button {
  color:#333!important;background:#ffffffc9!important;
  border:1px solid #ddd!important;border-radius:20px!important;
}
/* 2. 作者原版输入：悬浮玻璃细胶囊；保留糯米机真实语音输入、表情、发送和展开按钮。 */
.sully-chat-root .sully-chat-inputbar {
  background:transparent!important;
  border:0!important;box-shadow:none!important;
  isolation:isolate;
}
.sully-chat-root .sully-chat-inputbar::before {
  content:"";position:absolute;left:0;right:0;top:-12px;bottom:0;
  pointer-events:none;z-index:-1;
  background:linear-gradient(to top,rgba(255,255,255,.7),rgba(255,255,255,.37) 55%,transparent);
  backdrop-filter:blur(4px) saturate(120%);
  -webkit-backdrop-filter:blur(4px) saturate(120%);
  mask-image:linear-gradient(to top,#000 50%,transparent);
  -webkit-mask-image:linear-gradient(to top,#000 50%,transparent);
}
.sully-chat-root .sully-chat-composer {
  display:flex!important;align-items:center!important;
  gap:7px!important;
  padding:7px 10px max(11px,env(safe-area-inset-bottom))!important;
  min-width:0!important;
}
.sully-chat-root .sully-chat-actions-button {
  width:43px!important;height:43px!important;
  flex:0 0 43px!important;
  margin:0!important;padding:7px!important;
  color:#1a1a1a!important;
  border:0!important;border-radius:50%!important;
  background-color:var(--silent-glass)!important;
  background-image:url("https://i.imgant.com/v2/L06lLMZ.png")!important;
  background-position:center!important;background-size:contain!important;background-repeat:no-repeat!important;
  box-shadow:var(--silent-light-shadow)!important;
}
.sully-chat-root .sully-chat-input-wrap {
  position:relative!important;
  height:auto!important;min-height:43px!important;
  border:0!important;border-radius:50px!important;
  background:var(--silent-glass)!important;
  box-shadow:var(--silent-light-shadow)!important;
  flex:1 1 auto!important;min-width:0!important;
  padding:0 4px!important;
  overflow:visible!important;
}
.sully-chat-root .sully-chat-textarea {
  min-width:0!important;min-height:20px!important;
  max-height:120px!important;
  padding:8px 6px 8px 12px!important;
  color:#1a1a1a!important;
  font-size:14px!important;line-height:1.4!important;
  border:0!important;box-shadow:none!important;
  background:transparent!important;
  resize:none!important;
}
.sully-chat-root .sully-chat-textarea::placeholder {color:transparent!important;}
.sully-chat-root .sully-chat-input-wrap:has(.sully-chat-textarea:placeholder-shown):not(:focus-within)::after {
  content:"imonly temporary 2 u";
  pointer-events:none;position:absolute;left:17px;top:50%;
  transform:translateY(-50%);
  color:#8e8e8e;font-size:12px;line-height:1.2;
  white-space:nowrap;max-width:calc(100% - 92px);
  overflow:hidden;text-overflow:ellipsis;
}
.sully-chat-root .sully-chat-input-wrap button[aria-label="表情面板"],
.sully-chat-root .sully-chat-voice-trigger {
  width:30px!important;height:35px!important;
  min-width:30px!important;flex:0 0 30px!important;
  color:#1a1a1a!important;margin:0!important;
  padding:4px!important;border-radius:50%!important;
}
.sully-chat-root .sully-chat-send-button {
  width:43px!important;height:43px!important;
  min-width:43px!important;flex:0 0 43px!important;
  margin:0!important;padding:0!important;
  border:0!important;border-radius:50%!important;
  color:#fff!important;background-color:#1a1a1a!important;
  background-image:url("https://i.imgant.com/v2/n9OXMPV.png")!important;
  background-size:cover!important;background-position:center!important;background-repeat:no-repeat!important;
  box-shadow:0 3px 9px #0002!important;
}
.sully-chat-root .sully-chat-panel {
  background:rgba(255,255,255,.96)!important;
  color:#1a1a1a!important;
  border-color:#ececec!important;
}
/* 3. 原版紧凑连发：首条带铭牌、最后一条带头像，绝不在空槽上画圈。 */
.sully-chat-root .sully-chat-message:not(.sully-chat-message-module) {
  position:relative!important;
  margin-top:2px!important;margin-bottom:0!important;
  align-items:flex-end!important;
  min-width:0!important;
}
.sully-chat-root .sully-chat-message-group-first:not(.sully-chat-message-module) {
  margin-top:26px!important;
}
.sully-chat-root .sully-chat-message-group-last:not(.sully-chat-message-module) {
  margin-bottom:16px!important;
}
.sully-chat-root .sully-chat-message-content:not(.sully-html-wrap) {
  min-width:0!important;
  max-width:min(82%,calc(100% - 43px))!important;
}
.sully-chat-root .sully-chat-message-module .sully-chat-message-content {
  max-width:100%!important;
}
.sully-chat-root .sully-bubble-user,.sully-chat-root .sully-bubble-ai {
  position:relative!important;
  max-width:100%!important;
  overflow-wrap:break-word!important;
  background-image:none!important;
  border:0!important;
  box-shadow:none!important;
  padding:8px 14px!important;
  font-size:14px!important;
  line-height:1.35!important;
  transition:background-color .15s ease;
}
.sully-chat-root .sully-bubble-user,.sully-chat-root .sully-bubble-user * {
  --silent-bubble-text:#fff;
}
.sully-chat-root .sully-bubble-ai,.sully-chat-root .sully-bubble-ai * {
  --silent-bubble-text:#000;
}
.sully-chat-root .sully-bubble-user {
  background:#1a1a1a!important;
  color:#fff!important;
}
.sully-chat-root .sully-bubble-ai {
  background:#eee!important;
  color:#000!important;
}
/* Group shape: original single / first / middle / last geometry. */
.sully-chat-root .sully-chat-message-group-first.sully-chat-message-group-last .sully-bubble-ai {border-radius:20px!important;}
.sully-chat-root .sully-chat-message-group-first:not(.sully-chat-message-group-last) .sully-bubble-ai {border-radius:20px 20px 20px 6px!important;}
.sully-chat-root .sully-chat-message:not(.sully-chat-message-group-first):not(.sully-chat-message-group-last) .sully-bubble-ai {border-radius:6px 20px 20px 6px!important;}
.sully-chat-root .sully-chat-message-group-last:not(.sully-chat-message-group-first) .sully-bubble-ai {border-radius:6px 20px 20px 20px!important;}
.sully-chat-root .sully-chat-message-group-first.sully-chat-message-group-last .sully-bubble-user {border-radius:20px!important;}
.sully-chat-root .sully-chat-message-group-first:not(.sully-chat-message-group-last) .sully-bubble-user {border-radius:20px 20px 6px 20px!important;}
.sully-chat-root .sully-chat-message:not(.sully-chat-message-group-first):not(.sully-chat-message-group-last) .sully-bubble-user {border-radius:20px 6px 6px 20px!important;}
.sully-chat-root .sully-chat-message-group-last:not(.sully-chat-message-group-first) .sully-bubble-user {border-radius:20px 6px 20px 20px!important;}
.sully-chat-root .sully-bubble-user::before,.sully-chat-root .sully-bubble-user::after,
.sully-chat-root .sully-bubble-ai::before,.sully-chat-root .sully-bubble-ai::after {
  /* single-row native tails only; labels are added below to the first card */
  content:none;display:none;
}
/* 3a. The author puts a small CHAR / USER plate and signature above each first bubble.
       Use native group-first/group-last markers, not an invented HTML node. */
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message-group-first:not(.sully-chat-message-module) .sully-bubble-ai::before,
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message-group-first:not(.sully-chat-message-module) .sully-bubble-user::before {
  display:block!important;
  position:absolute!important;top:-23px;
  z-index:5;pointer-events:none;
  background:#1a1a1a;color:white;
  padding:3px 6px;border-radius:2px;
  font:700 10px/1 system-ui;box-shadow:0 2px 4px #00000016;
  letter-spacing:.5px;white-space:nowrap;
}
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message-group-first:not(.sully-chat-message-module) .sully-bubble-ai::before {
  content:"char";left:2px;
}
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message-group-first:not(.sully-chat-message-module) .sully-bubble-user::before {
  content:"user";right:2px;
}
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message-group-first:not(.sully-chat-message-module) .sully-bubble-ai::after,
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message-group-first:not(.sully-chat-message-module) .sully-bubble-user::after {
  display:block!important;
  position:absolute!important;top:-24px;
  z-index:5;pointer-events:none;
  background:transparent;color:#1a1a1a;
  font:500 12px/1.2 system-ui;
  white-space:nowrap;max-width:120px;text-overflow:ellipsis;overflow:hidden;
}
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message-group-first:not(.sully-chat-message-module) .sully-bubble-ai::after {
  content:"𝑬𝒗𝒊𝒍𝒐𝒗𝒆";left:45px;
}
.sully-chat-root:not(.sully-chat-group-root) .sully-chat-message-group-first:not(.sully-chat-message-module) .sully-bubble-user::after {
  content:"𝑯𝒆𝒂𝒓𝒕𝒇𝒆𝒍𝒕𝑻𝒆𝒂𝒓";right:46px;
}
/* 4. Only visibly rendered avatars get original black ring and + badge.
      Empty grouped placeholders MUST remain transparent and borderless. */
.sully-chat-root .sully-chat-message-avatar:not(.sully-chat-avatar-wrap):not(:has(.sully-chat-message-avatar-img)) {
  background:transparent!important;border:0!important;outline:0!important;
  padding:0!important;box-shadow:none!important;
}
.sully-chat-root .sully-chat-avatar-wrap {
  position:relative!important;
  background:transparent!important;
  overflow:visible!important;
  border-radius:50%!important;
  flex-shrink:0!important;
  border:0!important;padding:0!important;
  box-shadow:none!important;
}
.sully-chat-root .sully-chat-avatar-wrap::before {
  content:"";position:absolute!important;
  inset:-1px -2px -2px -1px;
  border:2px solid #1a1a1a!important;
  border-radius:50%!important;
  z-index:2;pointer-events:none;
}
.sully-chat-root .sully-chat-avatar-wrap::after {
  content:"+";position:absolute!important;
  right:-2px;bottom:0;
  width:14px;height:14px;
  display:flex;align-items:center;justify-content:center;
  border:2px solid #fff;border-radius:50%;
  box-sizing:border-box;background:#1a1a1a;color:white;
  font:800 12px/1 system-ui;
  z-index:5;pointer-events:none;
}
.sully-chat-root .sully-chat-avatar-wrap .sully-chat-message-avatar-img {
  width:100%!important;height:100%!important;
  object-fit:cover!important;border-radius:50%!important;
  border:0!important;outline:none!important;padding:0!important;
  box-shadow:none!important;
}
.sully-chat-root .sully-chat-avatar-frame {
  /* Keep any selected user avatar accessory visible; original black frame is a separate outline. */
  pointer-events:none!important;
}
.sully-chat-root .sully-chat-group-root .sully-chat-message-sender,
.sully-chat-root.sully-chat-group-root .sully-chat-message-sender {
  color:#8e8e8e!important;font-size:11px!important;
}
/* 5. Standalone reply strip resembling original detached reply card.
      Preserve native reply text and accessible interaction. */
.sully-chat-root .sully-chat-reply {
  position:relative!important;display:flex!important;
  flex-direction:column!important;
  min-width:0!important;max-width:min(200px,100%)!important;
  padding:6px 12px!important;margin-bottom:4px!important;
  border:0!important;border-radius:12px!important;
  background:#00000008!important;color:#8e8e8e!important;
  opacity:1!important;font-size:12px!important;
  gap:3px!important;line-height:1.4!important;
}
.sully-chat-root .sully-bubble-user .sully-chat-reply {
  background:rgba(255,255,255,.12)!important;
  color:#f3f3f3!important;
}
.sully-chat-root .sully-chat-reply::before {
  content:"";position:absolute;top:20%;bottom:20%;left:0;width:2px;
  background:#1a1a1a;border-radius:2px;pointer-events:none;
}
.sully-chat-root .sully-bubble-user .sully-chat-reply::before {background:#fff;}
.sully-chat-root .sully-qq-quote,.sully-chat-root .sully-facebook-reply {
  max-width:100%!important;
  border-radius:12px!important;font-size:12px!important;
}
/* 6. Original image sizing, without hiding interactions or clipping interactive cards. */
.sully-chat-root .sully-chat-card[data-card-kind="image"] .chat-image-thumbnail,
.sully-chat-root .sully-chat-card[data-card-kind="image"] img {
  max-width:min(200px,100%)!important;
  max-height:280px!important;
  object-fit:contain!important;border-radius:8px!important;
}
.sully-chat-root .sully-chat-card[data-card-kind="emoji"] img {
  max-width:min(170px,100%)!important;
  height:auto!important;object-fit:contain!important;
}
.sully-chat-root .sully-voice-bar {
  max-width:100%!important;
  border-radius:14px!important;
}
.sully-chat-root .sully-voice-bar-shell {min-width:0!important;}
.sully-chat-root .sully-voice-bar-transcript {
  font-size:12px!important;line-height:1.4!important;
}
/* 7. Thinking chain: author original tweet-like white card with blue title,
      preserving native expand/collapse and copy instead of fake buttons. */
.sully-chat-root .sully-psyche {max-width:100%!important;}
.sully-chat-root .sully-psyche-card {
  background:#fff!important;border:1px solid #ebeef0!important;
  border-radius:16px!important;
  box-shadow:0 4px 12px #0000000b!important;
  color:#0f1419!important;
  padding:16px!important;min-width:0!important;
}
.sully-chat-root .sully-psyche-title {
  color:#1d9bf0!important;
  font-size:13px!important;letter-spacing:.04em!important;
}
.sully-chat-root .sully-psyche-preview {
  color:#8e8e8e!important;font:italic 13px/1.5 system-ui!important;
}
.sully-chat-root .sully-psyche-status {
  color:#536471!important;font-size:10px!important;
  text-shadow:none!important;
}
.sully-chat-root .sully-psyche-body {
  color:#0f1419!important;font:14px/1.5 system-ui!important;
  white-space:pre-wrap!important;
}
/* 8. Original sticker transfer card, with reliable native pending/accepted/returned affordances. */
.sully-chat-root .sully-chat-transfer-card {
  position:relative!important;display:block!important;
  width:min(250px,100%)!important;min-height:110px!important;
  padding:12px 16px!important;
  max-width:100%!important;
  border:0!important;border-radius:8px!important;
  background-color:#1a1a1a!important;
  background-image:linear-gradient(to bottom,#00000010,#0000008a),url("https://i.imgant.com/v2/0iF6jgl.jpeg")!important;
  background-position:center!important;background-size:100% 100%!important;
  background-repeat:no-repeat!important;
  box-shadow:none!important;
  color:#fff!important;
  overflow:hidden!important;
}
.sully-chat-root .sully-chat-transfer-card .sully-chat-transfer-amount {
  color:#fff!important;font-size:25px!important;font-weight:800!important;
  line-height:1.15!important;text-shadow:0 1px 4px #0007!important;
}
.sully-chat-root .sully-chat-transfer-card .sully-chat-transfer-brand {
  color:#f1f1f1!important;font-size:11px!important;
}
.sully-chat-root .sully-chat-transfer-card .sully-chat-transfer-note,
.sully-chat-root .sully-chat-transfer-card .sully-chat-transfer-recipient {
  color:#f1f1f1!important;font-size:11px!important;
  text-shadow:0 1px 2px #0008!important;
}
.sully-chat-root .sully-chat-transfer-card .sully-chat-transfer-status {
  background:#ffffff36!important;color:#fff!important;
  border:1px solid #ffffff45!important;border-radius:12px!important;
}
.sully-chat-root .sully-chat-transfer-receipt {
  background:#eee!important;color:#1a1a1a!important;
  border:1px solid #d6d6d6!important;
  border-radius:12px!important;
  max-width:100%!important;
}
