/* 作者装饰先，禁止叠画原生系统图标；但可操作性与按钮禁用保留。 */
.sully-chat-root .sully-chat-composer > .sully-chat-actions-button > svg {display:none!important;}
.sully-chat-root .sully-chat-composer > .sully-chat-send-button:is([aria-label="发送文字"],[aria-label="生成回复"]) > svg {display:none!important;}
.sully-chat-root .sully-chat-composer > .sully-chat-actions-button,
.sully-chat-root .sully-chat-composer > .sully-chat-send-button,
.sully-chat-root .sully-chat-input-wrap button[aria-label="表情面板"],
.sully-chat-root .sully-chat-input-wrap .sully-chat-voice-trigger {
  touch-action:manipulation;pointer-events:auto!important;
}
/* 任何状态都不把语音弹层压在输入区下面，也不吞虚拟键盘焦点。 */
.sully-chat-root .sully-chat-inputbar .sully-chat-voice-menu {
  z-index:80!important;
}
/* 防止窄屏头像/通话/闪电互压，不破坏标题自然省略号。 */
@media(max-width:390px) {
 .sully-chat-root .sully-chat-header {padding-inline:10px!important;}
 .sully-chat-root .sully-chat-header .sully-chat-profile {margin-inline:4px!important;}
 .sully-chat-root .sully-chat-composer {padding-inline:8px!important;gap:5px!important;}
 .sully-chat-root .sully-chat-composer > .sully-chat-input-wrap {padding-right:41px!important;}
 .sully-chat-root .sully-chat-composer > .sully-chat-send-button {right:11px!important;}
 .sully-chat-root .sully-chat-input-wrap button[aria-label="表情面板"],
 .sully-chat-root .sully-chat-input-wrap .sully-chat-voice-trigger {
   width:29px!important;min-width:29px!important;flex-basis:29px!important;
 }
}
@media(max-width:345px) {
 .sully-chat-root .sully-chat-header .sully-chat-back {width:38px!important;min-width:38px!important;flex-basis:38px!important;}
 .sully-chat-root .sully-chat-header .sully-chat-trigger {width:37px!important;min-width:37px!important;flex-basis:37px!important;}
 .sully-chat-root .sully-chat-header button[aria-label="电话"] {width:35px!important;min-width:35px!important;flex-basis:35px!important;}
 .sully-chat-root .sully-chat-composer > .sully-chat-actions-button {flex:0 0 38px!important;width:38px!important;}
 .sully-chat-root .sully-chat-input-wrap button[aria-label="表情面板"],
 .sully-chat-root .sully-chat-input-wrap .sully-chat-voice-trigger {
   width:26px!important;min-width:26px!important;flex-basis:26px!important;
 }
 .sully-chat-root .sully-chat-input-wrap .sully-chat-textarea {padding-left:7px!important;padding-right:2px!important;}
}
